import type {
  ProfileObservation,
  ProfileReference,
} from '../../types/design-profile';
import type { ProfileRecords } from '../../storage/profiles/ProfileRecords';
import { provisionalDescription } from '../../storage/profiles/provisionalDescription';

export const saveProvisionalObservation = (
  records: Pick<
    ProfileRecords,
    'reference' | 'observation' | 'saveObservation'
  >,
  reference: ProfileReference,
): void => {
  if (
    records.reference(reference.id)?.revision !== reference.revision ||
    records.observation(reference.id)
  )
    return;
  records.saveObservation({
    referenceId: reference.id,
    revision: reference.revision,
    description: provisionalDescription(reference),
    runtime: 'user',
    evidence: 'provisional',
  });
};

export const profileEvidence = (
  reference: ProfileReference,
  observation: ProfileObservation,
): string => {
  const parts = [observation.description];
  if (reference.note)
    parts.push(`User note for this direction: ${reference.note}`);
  if (reference.variant) {
    const { projectId, sessionId, variantId } = reference.variant;
    parts.push(`Saved direction: ${projectId}/${sessionId}:${variantId}`);
  }
  return parts.join('\n');
};
